import queue


def accepted(cap: int, xs: list[int]) -> int:
    """Count how many elements of xs a bounded queue accepts without blocking.

    Creates a queue.Queue holding at most cap integers, then tries to put
    each element of xs in order with put_nowait. Stops at the first
    queue.Full and returns the number of puts accepted before that point.
    A non-positive cap means the queue can hold nothing, so the result is 0
    (unlike queue.Queue, where maxsize <= 0 would mean unbounded).
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_stops_when_full() -> None:
    assert accepted(3, [1, 2, 3, 4, 5]) == 3


def test_capacity_larger_than_input() -> None:
    assert accepted(10, [1, 2, 3]) == 3


def test_exact_fit() -> None:
    assert accepted(3, [7, 8, 9]) == 3


def test_empty_input() -> None:
    assert accepted(5, []) == 0


def test_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_negative_capacity() -> None:
    assert accepted(-2, [1, 2, 3]) == 0


def test_duplicates_are_counted() -> None:
    assert accepted(2, [4, 4, 4, 4]) == 2


def test_single_slot() -> None:
    assert accepted(1, [9, 8]) == 1
